"""Evaluate changes to declared source dependencies."""

from __future__ import annotations

import json
from typing import Any, Mapping

_MISSING = {"kind": "missing"}


def _canonical_json(value: Any) -> str:
    """Return a stable, type-sensitive representation of a JSON value."""
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def evaluate(request: Mapping[str, Any], policy: Mapping[str, Any]) -> dict[str, Any]:
    """Evaluate complete states for relevant declared source paths."""
    declared = request.get("declared", ())
    ignored = set(policy.get("ignored", ()))
    saved = request.get("saved", {})
    current = request.get("current", {})

    changed = []
    for path in set(declared):
        if path in ignored:
            continue
        before = saved.get(path, _MISSING)
        after = current.get(path, _MISSING)
        if _canonical_json(before) != _canonical_json(after):
            changed.append(path)

    changed.sort()
    return {"needs_review": bool(changed), "changed": changed}

